nixos-fw.content:
set temp-ports {
  comment "Temporarily opened ports"
  type inet_proto . inet_service
  flags interval
  auto-merge
}

chain rpfilter {
  type filter hook prerouting priority mangle + 10; policy drop;

  meta nfproto ipv4 udp sport . udp dport { 67 . 68, 68 . 67 } accept comment "DHCPv4 client/server"
  fib saddr . mark . iif oif exists accept

  jump rpfilter-allow



}


chain rpfilter-allow {

}

chain input {
  type filter hook input priority filter; policy drop;

  iifname { "lo" } accept comment "trusted interfaces"

  # Multicast ICMPv6 echo replies get marked as invalid by conntrack.
  # Accept them before conntrack to avoid dropped replies.
  icmpv6 type echo-reply accept

  # Some ICMPv6 types like NDP is untracked
  ct state vmap {
    invalid : drop,
    established : accept,
    related : accept,
    new : jump input-allow,
    untracked: jump input-allow,
  }







}

chain input-allow {

   tcp dport { 22, 636, 1108 } accept
 udp dport { 5353 } accept
iifname enp2s0 tcp dport { 2208 } accept
iifname enp2s0 udp dport { 2108, 2207, 4171, 4175, 4179, 17780, 17781, 17782, 17783, 17784, 17785, 27015 } accept
iifname enp3s0 tcp dport { 443, 2208 } accept
iifname enp3s0 udp dport { 53, 67, 1108, 2108 } accept
iifname wireg0 tcp dport { 443, 3100, 3101, 3102, 3107, 3111, 9100 } accept
iifname wireg0 udp dport { 1108 } accept


  meta l4proto . th dport @temp-ports accept

  icmp type echo-request  accept comment "allow ping"


  icmpv6 type != { nd-redirect, 139 } accept comment "Accept all ICMPv6 messages except redirects and node information queries (type 139).  See RFC 4890, section 4.4."
  ip6 daddr fe80::/64 udp dport 546 accept comment "DHCPv6 client"



}

